using System.Text.Json;
using CREMS.Api.Controllers;
using CREMS.Api.Data;
using CREMS.Api.Domain.Assets;
using CREMS.Api.Domain.Common;
using CREMS.Api.Domain.Identity;
using CREMS.Api.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Caching.Memory;
using Xunit;
namespace CREMS.Api.Tests;
public sealed class AssetRegisterBehaviorTests
{
    private static CancellationToken T=>TestContext.Current.CancellationToken;
    private static SaveAssetRequest Request(Guid branch,Guid division)=>JsonSerializer.Deserialize<SaveAssetRequest>("{}")! with{AssetNumber=" new-1 ",Name=" Training equipment ",BranchId=branch,DivisionId=division,Type=AssetType.LightEquipment,Status=AssetStatus.Available,DailyRate=100,DefaultBondAmount=100,CurrentMeterReading=1000,MeterUnit="hours",RegistrationNumber=" REG-1 ",SerialNumber=" SER-1 ",Manufacturer=" Test ",Model=" Training ",PhotoUrlsJson="[]"};
    private static async Task<(AssetsController C,Asset A,SaveAssetRequest R)> Setup(ApplicationDbContext db,CustomerLicenceStorageBehaviorTests.EnvironmentFixture env,IMemoryCache? cache=null)
    {var(ctx,a)=await MaintenanceJobsTests.Setup(db);var d=new Division{Code="ASSET",Name="Asset division"};db.AddRange(d,new BranchDivision{BranchId=a.BranchId,DivisionId=d.Id});await db.SaveChangesAsync(T);return(new AssetsController(db,new CurrentStaffScope(db),env,cache){ControllerContext=ctx.ControllerContext},a,Request(a.BranchId,d.Id));}
    [Fact]public async Task Create_and_edit_preserve_meter_history_normalize_fields_and_invalidate_catalogue()
    {await using var db=MaintenanceJobsTests.Database();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();using var cache=new MemoryCache(new MemoryCacheOptions());var(c,a,r)=await Setup(db,env,cache);cache.Set("public-catalogue-bootstrap-v1","stale");var created=Assert.IsType<AssetResponse>(Assert.IsType<CreatedAtActionResult>((await c.Create(r,T)).Result).Value);Assert.Equal("NEW-1",created.AssetNumber);Assert.Equal("Training equipment",created.Name);Assert.Equal("REG-1",created.RegistrationNumber);Assert.Equal(1000,created.CurrentMeterReading);Assert.False(cache.TryGetValue("public-catalogue-bootstrap-v1",out _));var edited=Assert.IsType<AssetResponse>(Assert.IsType<OkObjectResult>((await c.Update(created.Id,r with{Name="Updated equipment",DailyRate=125,CurrentLocation=" Test yard "},T)).Result).Value);Assert.Equal("Updated equipment",edited.Name);Assert.Equal(125,edited.DailyRate);Assert.Equal("Test yard",edited.CurrentLocation);Assert.Equal(1000,edited.CurrentMeterReading);Assert.Contains(await db.AuditEvents.ToListAsync(T),x=>x.Action=="Asset created");Assert.Contains(await db.AuditEvents.ToListAsync(T),x=>x.Action=="Asset updated");}
    [Theory][InlineData(-1)][InlineData(1441)]public async Task Invalid_turnaround_is_rejected_before_creation(int minutes)
    {await using var db=MaintenanceJobsTests.Database();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var(c,a,r)=await Setup(db,env);Assert.IsType<BadRequestObjectResult>((await c.Create(r with{TurnaroundMinutes=minutes},T)).Result);Assert.IsType<BadRequestObjectResult>((await c.Update(a.Id,r with{TurnaroundMinutes=minutes},T)).Result);Assert.Equal(1,await db.Assets.CountAsync(T));}
    [Fact]public async Task Duplicate_numbers_inactive_branches_and_unknown_classifications_are_rejected()
    {await using var db=MaintenanceJobsTests.Database();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var(c,a,r)=await Setup(db,env);Assert.IsAssignableFrom<ObjectResult>((await c.Create(r with{AssetNumber=a.AssetNumber},T)).Result);Assert.Contains("already exists",JsonSerializer.Serialize(c.ModelState));c.ModelState.Clear();Assert.IsAssignableFrom<ObjectResult>((await c.Create(r with{DivisionId=null},T)).Result);c.ModelState.Clear();Assert.IsAssignableFrom<ObjectResult>((await c.Create(r with{AssetCategoryId=Guid.NewGuid()},T)).Result);c.ModelState.Clear();(await db.Branches.SingleAsync(T)).IsActive=false;await db.SaveChangesAsync(T);Assert.IsAssignableFrom<ObjectResult>((await c.Create(r,T)).Result);Assert.Equal(1,await db.Assets.CountAsync(T));}
    [Fact]public async Task Status_changes_and_cost_entries_are_persisted_with_actor_and_clean_strings()
    {await using var db=MaintenanceJobsTests.Database();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var(c,a,r)=await Setup(db,env);Assert.IsType<NoContentResult>(await c.SetStatus(a.Id,new(AssetStatus.Retired,false),T));Assert.Equal(AssetStatus.Retired,a.Status);Assert.False(a.IsActive);Assert.IsType<OkObjectResult>(await c.AddCost(a.Id,new(null,AssetCostCategory.Other," Cleaning ",20,new DateOnly(2026,1,1)," Supplier "," REF "),T));var cost=await db.AssetCostEntries.SingleAsync(T);Assert.Equal("Cleaning",cost.Description);Assert.Equal("Supplier",cost.Supplier);Assert.Equal("REF",cost.ReferenceNumber);Assert.Equal(20,cost.Amount);Assert.NotEqual(Guid.Empty,cost.RecordedByUserId);Assert.IsType<BadRequestObjectResult>(await c.AddCost(a.Id,new(Guid.NewGuid(),AssetCostCategory.Other,"Bad link",20,new DateOnly(2026,1,1),null,null),T));}
    [Fact]public async Task Photo_upload_encodes_full_and_thumbnail_then_delete_removes_both_files()
    {await using var db=MaintenanceJobsTests.Database();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var(c,a,r)=await Setup(db,env);Assert.IsType<OkObjectResult>(await c.UploadPhoto(a.Id,CustomerLicenceStorageBehaviorTests.Image(),T));var url=Assert.Single(JsonSerializer.Deserialize<string[]>(a.PhotoUrlsJson)!);Assert.EndsWith(".webp",url);var name=Path.GetFileName(url);var root=Path.Combine(env.ContentRootPath,"App_Data","asset-images",a.Id.ToString("N"));Assert.True(File.Exists(Path.Combine(root,name)));Assert.True(File.Exists(Path.Combine(root,Path.GetFileNameWithoutExtension(name)+".thumb.webp")));Assert.IsType<BadRequestResult>(await c.DeletePhoto(a.Id,"../"+name,T));Assert.IsType<OkObjectResult>(await c.DeletePhoto(a.Id,name,T));Assert.Empty(Directory.GetFiles(root));Assert.Empty(JsonSerializer.Deserialize<string[]>(a.PhotoUrlsJson)!);}
    [Theory][InlineData("file.txt","not image")][InlineData("file.png","not image")][InlineData("file.jpg","")]
    public async Task Invalid_photo_uploads_do_not_change_the_catalogue(string filename,string content)
    {await using var db=MaintenanceJobsTests.Database();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var(c,a,r)=await Setup(db,env);var bytes=System.Text.Encoding.UTF8.GetBytes(content);var file=new FormFile(new MemoryStream(bytes),0,bytes.Length,"file",filename);Assert.IsType<BadRequestObjectResult>(await c.UploadPhoto(a.Id,file,T));Assert.Empty(JsonSerializer.Deserialize<string[]>(a.PhotoUrlsJson)!);Assert.False(Directory.Exists(env.ContentRootPath));}
    [Fact]public async Task Missing_assets_and_anonymous_sessions_are_rejected()
    {await using var db=MaintenanceJobsTests.Database();using var env=new CustomerLicenceStorageBehaviorTests.EnvironmentFixture();var(c,a,r)=await Setup(db,env);var id=Guid.NewGuid();Assert.IsType<NotFoundResult>(await c.SetStatus(id,new(AssetStatus.Available,true),T));Assert.IsType<NotFoundResult>((await c.Update(id,r,T)).Result);Assert.IsType<NotFoundResult>(await c.UploadPhoto(id,CustomerLicenceStorageBehaviorTests.Image(),T));Assert.IsType<NotFoundResult>(await c.DeletePhoto(id,"missing.webp",T));c=new AssetsController(db,new CurrentStaffScope(db),env){ControllerContext=new(){HttpContext=new DefaultHttpContext()}};Assert.IsType<ForbidResult>((await c.Create(r,T)).Result);Assert.IsType<ForbidResult>(await c.SetStatus(a.Id,new(AssetStatus.Available,true),T));}
}
